/** Where inventory data came from and when it was read. */
export type Source = {
  /** RFC 3339 timestamp (UTC). */
  observedAt: string;
  provider: ProviderMode;
};

export type StateChange = {
  action: InstanceAction;
};

export type StepDto = {
  error?: string | null;
  instance: string;
  module: string;
  /** `pending`, `running`, `succeeded`, `failed` or `skipped`. */
  state: string;
};

/** One member's share of a pool. */
export type StorageMemberUsage = {
  member: string;
  totalBytes: number;
  usedBytes: number;
};

export type StoragePool = {
  description: string;
  driver: string;
  /** Cluster members it is created on; empty when unknown. */
  locations?: string[];
  name: string;
  status: string;
};

export type StoragePoolList = {
  items: StoragePool[];
  source: Source;
};

export type StoragePoolReport = {
  backupPool?: string | null;
  items: StoragePoolUsage[];
  source: Source;
  volumePool?: string | null;
};

export type StoragePoolUsage = {
  description: string;
  driver: string;
  /** Use per member as Incus reports it; a shared pool lists the first member that reported it. */
  members: StorageMemberUsage[];
  name: string;
  /** What Apelora uses it for: `volumes` (`APELORA_VOLUME_POOL`), `backups` (`APELORA_BACKUP_POOL`), or nothing. */
  role?: string | null;
  /** One pool every member reaches (clustered LVM, Ceph): its space is counted once. */
  shared: boolean;
  status: string;
  total?: null | HealthUsage;
  /** Members whose use could not be read, with the reason. */
  unreadable: string[];
};

export type StorageVolume = {
  application: string;
  /** Backups recorded for it. */
  backups: number;
  class: string;
  /** The Incus volume (`<instance>-<name>`). */
  incusName: string;
  instance: string;
  lastBackupAt?: string | null;
  member: string;
  module: string;
  /** The design's name (`data`). */
  name: string;
  pool: string;
  schedules: VolumeSchedules;
  sizeMib: number;
  state?: null | VolumeUse;
  usedBy: string[];
};

export type StorageVolumeList = {
  /** Where backups go; `None`: backups cannot be taken (`APELORA_BACKUP_POOL` is unset). */
  backupPool?: string | null;
  /** Why Incus could not be read (the list still shows Apelora's records). */
  incusError?: string | null;
  items: StorageVolume[];
  source: Source;
};

/** Facts about this control plane and the Incus release it is pinned to. */
export type SystemInfo = {
  apiVersion: string;
  /** The certificates Apelora uses to reach Incus and when they expire (empty with the mock). */
  certificates: CertificateStatus[];
  /** Incus as observed now: running version, clustering, or why it cannot be reached. (The public `/api/v1/health` says only whether it is reachable.) */
  incus: IncusStatus;
  /** Incus release Apelora is tested against (`upstream.lock.yaml`). */
  incusPinned: string;
  /** Incus LTS series the pin follows, e.g. "7.0". */
  incusSeries: string;
  /** Evidence recorded for the pin. */
  incusTestedWith: string;
  version: string;
};

export type TokenCreated = {
  info: TokenInfo;
  /** The token itself, shown only in this response. */
  token: string;
};

export type TokenInfo = {
  /** RFC 3339. */
  createdAt: string;
  expiresAt?: string | null;
  id: string;
  lastUsedAt?: string | null;
  name: string;
  revokedAt?: string | null;
  role: Role;
};

export type TokenList = {
  items: TokenInfo[];
};

export type UpdateApplication = {
  description?: string | null;
  icon?: string | null;
};

export type UserDto = {
  createdAt: string;
  disabled: boolean;
  displayName?: string | null;
  email?: string | null;
  id: string;
  issuer: string;
  lastSeenAt?: string | null;
  username?: string | null;
};

export type UserList = {
  items: UserDto[];
};

export type VersionDocument = {
  document: Record<string, unknown>;
  published: boolean;
};

export type VersionInfo = {
  createdAt: string;
  createdBy: string;
  draftVersion?: number | null;
  label?: string | null;
  published: boolean;
  revision: number;
};

export type VersionList = {
  items: VersionInfo[];
};

export type VolumeBackupItem = {
  /** The restore job that took it just before overwriting the volume. */
  beforeRestore?: string | null;
  member: string;
  /** The backup's Incus name. */
  name: string;
  pool: string;
  /** It exists in Incus; `None` when Incus could not be read. */
  present?: boolean | null;
  /** Made by the schedule (pruned to what the schedule keeps), not on request. */
  scheduled: boolean;
  sizeMib: number;
  /** When it was taken (RFC 3339): a restore brings back the data as it was then. */
  takenAt: string;
};

export type VolumeBackupList = {
  backupPool?: string | null;
  /** Oldest first. */
  items: VolumeBackupItem[];
  schedules: VolumeSchedules;
  source: Source;
};

/** The policy a volume is created under. Only `data-local` exists so far: persistent, one writer, on the member's own pool; moving it means stopping the instance. */
export type VolumeClass = "data-local";

/** What the volume holds: a mounted filesystem or a raw disk (virtual machines only). */
export type VolumeContent = "filesystem" | "block";

export type VolumeItem = {
  class: string;
  content: string;
  createdAt: string;
  /** The Incus volume (`<instance>-<name>`): what to type to delete it. */
  incusName: string;
  instance: string;
  /** Member of a member-local pool; empty on a standalone server. */
  member: string;
  module: string;
  /** The design's name (`data`). */
  name: string;
  pool: string;
  sizeMib: number;
  state: VolumeUse;
  /** Instances using it. */
  usedBy: string[];
};

/** A volume a module asks for. */
export type VolumeMount = {
  class?: VolumeClass;
  content?: VolumeContent;
  /** Name in the design, e.g. `data`: lowercase letters, digits and `-`, at most 16. */
  name: string;
  /** Where a filesystem volume is mounted inside the instance; none for a block volume. */
  path?: string | null;
  /** The pool the class resolves to. Set by the control plane, never by a caller. */
  pool?: string | null;
  sizeMib: number;
};

export type VolumeSchedules = {
  backups?: null | ScheduleState;
  snapshots?: null | ScheduleState;
};

/** What Incus reports about a recorded volume now. */
export type VolumeUse = "attached" | "retained" | "missing";

export type WhoAmI = {
  /** Permission ids held at some scope (what the UI may offer; the server decides each request). */
  capabilities: string[];
  /** The credential this request was made with: `identity-provider` (an OIDC access token), `session` (an Apelora session after a password or directory sign-in), `personal-token`, `service-token`, `api-token` (legacy) or `development`. */
  credential: string;
  /** Incus projects this control plane deploys into (`APELORA_DEPLOY_PROJECTS`). */
  deployProjects: string[];
  /** The user or service identity id; absent for legacy tokens. */
  id?: string | null;
  /** `user` (OIDC sign-in), `service` (automation identity), `legacy-token` or `development`. */
  kind: string;
  /** Signed in with a local account (username and password): may change their password here. */
  localAccount: boolean;
  name: string;
  /** What the older, coarse permissions amount to for this caller at platform level. */
  permissions: Permission[];
  /** Permission ids held across the whole platform. */
  platformPermissions: string[];
  role?: null | Role;
  /** The role assignments in force for this caller. */
  roles: RoleGrant[];
};

